const rows = $input.first().json;
const map = {};
if (Array.isArray(rows)) rows.forEach(r => { map[r.key] = r.value; });
const tema_semana = map['tema_semana'] || 'skincare — hidratação e barreira cutânea';
const tema_mes = map['tema_mes'] || 'skincare — proteção solar';
const tema_trimestre = map['tema_trimestre'] || 'skincare — anti-idade natural';
const numero_semana = Math.ceil(new Date().getDate() / 7);
return [{ json: { tema_semana, tema_mes, tema_trimestre, numero_semana, clima_semana: 'tropical — calor e umidade' } }];

const serpData = $('SerpAPI — Busca Skincare').item.json;
const tavilyData = $input.first().json;
let contextParts = [];
if (serpData.organic_results && Array.isArray(serpData.organic_results)) {
  const serpSnippets = serpData.organic_results.slice(0, 10).map((r, i) => `[Fonte ${i+1}] ${r.title||''}:\n${r.snippet||''}\nURL: ${r.link||''}`).join('\n\n');
  contextParts.push('=== Resultados SerpAPI ===\n' + serpSnippets);
}
if (tavilyData.results && Array.isArray(tavilyData.results)) {
  const tavilySnippets = tavilyData.results.slice(0, 5).map((r, i) => `[Tavily ${i+1}] ${r.title||''}:\n${r.content||''}\nURL: ${r.url||''}`).join('\n\n');
  contextParts.push('=== Resultados Tavily ===\n' + tavilySnippets);
}
const contexto_pesquisa = contextParts.join('\n\n');
const tema_semana = $('Extrair Temas do Supabase').item.json.tema_semana;
const clima_semana = $('Extrair Temas do Supabase').item.json.clima_semana;
return [{ json: { contexto_pesquisa, tema_semana, clima_semana } }];

const response = $input.first().json;
let html_content = '';

if (response.choices && response.choices.length > 0) {
  html_content = response.choices[0].message?.content || '';
} else if (response.content && Array.isArray(response.content)) {
  html_content = response.content[0]?.text || '';
} else {
  throw new Error('API não retornou conteúdo: ' + JSON.stringify(response).slice(0, 300));
}

// Strip markdown wrappers se GPT os incluiu
html_content = html_content.replace(/^```html\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```\s*$/, '').trim();

// Dados para a capa
const tema = (() => { try { return $('Extrair Temas do Supabase').item.json.tema_semana || ''; } catch(e) { return ''; } })();
const dataFmt = new Date().toLocaleDateString('pt-BR', {day:'2-digit', month:'long', year:'numeric'});
const imagem_url = (() => { try { return $('Extrair URL Imagem').item.json.imagem_url || ''; } catch(e) { return ''; } })();
const imagem_autor = (() => { try { return $('Extrair URL Imagem').item.json.imagem_autor || ''; } catch(e) { return ''; } })();

