const now = new Date();
const year = now.getFullYear();
const week = String(Math.ceil((now - new Date(year,0,1)) / 604800000)).padStart(2,'0');
const month = String(now.getMonth()+1).padStart(2,'0');

const filenamePago   = 'pdf-semanal-' + year + '-semana' + week + '.pdf';
const filenameGratis = 'pdf-gratuito-' + year + '-semana' + week + '.pdf';
const pathPago       = year + '/' + month + '/' + filenamePago;
const pathGratis     = year + '/' + month + '/' + filenameGratis;

return [{
  json: {
    ...$input.first().json,
    filename_pago:   filenamePago,
    filename_gratis: filenameGratis,
    path_pago:       pathPago,
    path_gratis:     pathGratis
  },
  binary: $input.first().binary
}];

